class _UniffiFfiConverterOptionalSequenceString(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiFfiConverterSequenceString.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiFfiConverterSequenceString.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiFfiConverterSequenceString.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")

class _UniffiFfiConverterSequenceUInt16(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        for item in value:
            _UniffiFfiConverterUInt16.check_lower(item)

    @classmethod
    def write(cls, value, buf):
        items = len(value)
        buf.write_i32(items)
        for item in value:
            _UniffiFfiConverterUInt16.write(item, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative sequence length")

        return [
            _UniffiFfiConverterUInt16.read(buf) for i in range(count)
        ]

@dataclass
class Container:
    """
    An extra container next to a sandbox (a compose-style sidecar),
    addressed by name on every runtime: the sandbox reaches it at its
    `name` (on its `ports`), it reaches the sandbox at `main`, and
    `services` may name its ports (`{"db": 5432}`). Local containers run it
    in the sandbox's network namespace (`localhost` works too; needs
    `runtime="runc"`); cloud gVisor sandboxes run it in the same pod; cloud
    VM (KubeVirt) sandboxes run it in a companion pod named in the guest's
    `/etc/hosts`. Local VM sandboxes refuse sidecars. With sidecars the
    service names `main`, `sidecars` and `sc` are reserved.
"""
    def __init__(self, *, image:str, command:typing.Optional[typing.List[str]] = _DEFAULT, env:dict[str, str] = _DEFAULT, ports:typing.List[int] = _DEFAULT, name:typing.Optional[str] = _DEFAULT):
        self.image = image
        if command is _DEFAULT:
            self.command = None
        else:
            self.command = command
        if env is _DEFAULT:
            self.env = {}
        else:
            self.env = env
        if ports is _DEFAULT:
            self.ports = []
        else:
            self.ports = ports
        if name is _DEFAULT:
            self.name = None
        else:
            self.name = name




    def __str__(self):
        return "Container(image={}, command={}, env={}, ports={}, name={})".format(self.image, self.command, self.env, self.ports, self.name)
    def __eq__(self, other):
        if self.image != other.image:
            return False
        if self.command != other.command:
            return False
        if self.env != other.env:
            return False
        if self.ports != other.ports:
            return False
        if self.name != other.name:
            return False
        return True

