class CuaMode(enum.Enum):
    """
    Where the SDK runtime lives.
"""

    EMBEDDED = 0
    """
    In this process.
"""

    DAEMON = 1
    """
    In a `cua daemon`.
"""



class _UniffiFfiConverterTypeCuaMode(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return CuaMode.EMBEDDED
        if variant == 2:
            return CuaMode.DAEMON
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == CuaMode.EMBEDDED:
            return
        if value == CuaMode.DAEMON:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == CuaMode.EMBEDDED:
            buf.write_i32(1)
        if value == CuaMode.DAEMON:
            buf.write_i32(2)



