class RuntimeCheckStatus(enum.Enum):
    """
    Status of one local runtime component.
"""

    OK = 0
    """
    Present and usable.
"""

    INSTALLABLE = 1
    """
    Missing; `setup` can provision it.
"""

    ERROR = 2
    """
    Missing or broken; needs user action.
"""

    NOT_APPLICABLE = 3
    """
    Not used on this host.
"""

    UNKNOWN = 4
    """
    Not reported.
"""



class _UniffiFfiConverterTypeRuntimeCheckStatus(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return RuntimeCheckStatus.OK
        if variant == 2:
            return RuntimeCheckStatus.INSTALLABLE
        if variant == 3:
            return RuntimeCheckStatus.ERROR
        if variant == 4:
            return RuntimeCheckStatus.NOT_APPLICABLE
        if variant == 5:
            return RuntimeCheckStatus.UNKNOWN
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == RuntimeCheckStatus.OK:
            return
        if value == RuntimeCheckStatus.INSTALLABLE:
            return
        if value == RuntimeCheckStatus.ERROR:
            return
        if value == RuntimeCheckStatus.NOT_APPLICABLE:
            return
        if value == RuntimeCheckStatus.UNKNOWN:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == RuntimeCheckStatus.OK:
            buf.write_i32(1)
        if value == RuntimeCheckStatus.INSTALLABLE:
            buf.write_i32(2)
        if value == RuntimeCheckStatus.ERROR:
            buf.write_i32(3)
        if value == RuntimeCheckStatus.NOT_APPLICABLE:
            buf.write_i32(4)
        if value == RuntimeCheckStatus.UNKNOWN:
            buf.write_i32(5)



