# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
ImageLayer.APT_INSTALL = type("ImageLayer.APT_INSTALL", (ImageLayer.APT_INSTALL, ImageLayer,), {})  # type: ignore
ImageLayer.PIP_INSTALL = type("ImageLayer.PIP_INSTALL", (ImageLayer.PIP_INSTALL, ImageLayer,), {})  # type: ignore
ImageLayer.UV_INSTALL = type("ImageLayer.UV_INSTALL", (ImageLayer.UV_INSTALL, ImageLayer,), {})  # type: ignore
ImageLayer.RUN = type("ImageLayer.RUN", (ImageLayer.RUN, ImageLayer,), {})  # type: ignore
ImageLayer.APP_INSTALL = type("ImageLayer.APP_INSTALL", (ImageLayer.APP_INSTALL, ImageLayer,), {})  # type: ignore




class _UniffiFfiConverterTypeImageLayer(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return ImageLayer.APT_INSTALL(
                _UniffiFfiConverterSequenceString.read(buf),
            )
        if variant == 2:
            return ImageLayer.PIP_INSTALL(
                _UniffiFfiConverterSequenceString.read(buf),
            )
        if variant == 3:
            return ImageLayer.UV_INSTALL(
                _UniffiFfiConverterSequenceString.read(buf),
            )
        if variant == 4:
            return ImageLayer.RUN(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 5:
            return ImageLayer.APP_INSTALL(
                _UniffiFfiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_APT_INSTALL():
            _UniffiFfiConverterSequenceString.check_lower(value.packages)
            return
        if value.is_PIP_INSTALL():
            _UniffiFfiConverterSequenceString.check_lower(value.packages)
            return
        if value.is_UV_INSTALL():
            _UniffiFfiConverterSequenceString.check_lower(value.packages)
            return
        if value.is_RUN():
            _UniffiFfiConverterString.check_lower(value.command)
            return
        if value.is_APP_INSTALL():
            _UniffiFfiConverterString.check_lower(value.app_id)
            return
        raise ValueError(value)

