    def write(value, buf):
        if value.is_APT_INSTALL():
            buf.write_i32(1)
            _UniffiFfiConverterSequenceString.write(value.packages, buf)
        if value.is_PIP_INSTALL():
            buf.write_i32(2)
            _UniffiFfiConverterSequenceString.write(value.packages, buf)
        if value.is_UV_INSTALL():
            buf.write_i32(3)
            _UniffiFfiConverterSequenceString.write(value.packages, buf)
        if value.is_RUN():
            buf.write_i32(4)
            _UniffiFfiConverterString.write(value.command, buf)
        if value.is_APP_INSTALL():
            buf.write_i32(5)
            _UniffiFfiConverterString.write(value.app_id, buf)



