class SandboxStatus(enum.Enum):
    """
    Coarse lifecycle status.
"""

    RUNNING = 0
    """
    Running (or bound).
"""

    SUSPENDED = 1
    """
    Suspended or scaled to zero.
"""

    STOPPED = 2
    """
    Stopped.
"""

    PROVISIONING = 3
    """
    Starting.
"""

    UNKNOWN = 4
    """
    Unknown; see `SandboxInfo.status_detail`.
"""



class _UniffiFfiConverterTypeSandboxStatus(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return SandboxStatus.RUNNING
        if variant == 2:
            return SandboxStatus.SUSPENDED
        if variant == 3:
            return SandboxStatus.STOPPED
        if variant == 4:
            return SandboxStatus.PROVISIONING
        if variant == 5:
            return SandboxStatus.UNKNOWN
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == SandboxStatus.RUNNING:
            return
        if value == SandboxStatus.SUSPENDED:
            return
        if value == SandboxStatus.STOPPED:
            return
        if value == SandboxStatus.PROVISIONING:
            return
        if value == SandboxStatus.UNKNOWN:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == SandboxStatus.RUNNING:
            buf.write_i32(1)
        if value == SandboxStatus.SUSPENDED:
            buf.write_i32(2)
        if value == SandboxStatus.STOPPED:
            buf.write_i32(3)
        if value == SandboxStatus.PROVISIONING:
            buf.write_i32(4)
        if value == SandboxStatus.UNKNOWN:
            buf.write_i32(5)








class SandboxPhase(enum.Enum):
    """
    Portable lifecycle phase, the same words local and in the cloud.
"""

    PROVISIONING = 0
    """
    Being created (cloud: capacity is being provisioned).
"""

    STARTING = 1
    """
    Booting; readiness probes have not passed yet.
"""

    READY = 2
    """
    Running and ready.
"""

    STOPPED = 3
    """
    Stopped or suspended.
"""



class _UniffiFfiConverterTypeSandboxPhase(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return SandboxPhase.PROVISIONING
        if variant == 2:
            return SandboxPhase.STARTING
        if variant == 3:
            return SandboxPhase.READY
        if variant == 4:
            return SandboxPhase.STOPPED
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == SandboxPhase.PROVISIONING:
            return
        if value == SandboxPhase.STARTING:
            return
        if value == SandboxPhase.READY:
            return
        if value == SandboxPhase.STOPPED:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == SandboxPhase.PROVISIONING:
            buf.write_i32(1)
        if value == SandboxPhase.STARTING:
            buf.write_i32(2)
        if value == SandboxPhase.READY:
            buf.write_i32(3)
        if value == SandboxPhase.STOPPED:
            buf.write_i32(4)



