class ImageFormat(enum.Enum):
    """
    Screenshot encoding.
"""

    PNG = 0
    """
    PNG.
"""

    JPEG = 1
    """
    JPEG.
"""

    WEBP = 2
    """
    WebP.
"""



class _UniffiFfiConverterTypeImageFormat(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return ImageFormat.PNG
        if variant == 2:
            return ImageFormat.JPEG
        if variant == 3:
            return ImageFormat.WEBP
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == ImageFormat.PNG:
            return
        if value == ImageFormat.JPEG:
            return
        if value == ImageFormat.WEBP:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == ImageFormat.PNG:
            buf.write_i32(1)
        if value == ImageFormat.JPEG:
            buf.write_i32(2)
        if value == ImageFormat.WEBP:
            buf.write_i32(3)



