class LoginMethod(enum.Enum):
    """
    How a sign-in proceeds.
"""

    BROWSER = 0
    """
    Open `url` in a browser on this machine; it redirects back here.
"""

    DEVICE = 1
    """
    Open `url` on any device and enter `user_code`.
"""



class _UniffiFfiConverterTypeLoginMethod(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return LoginMethod.BROWSER
        if variant == 2:
            return LoginMethod.DEVICE
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == LoginMethod.BROWSER:
            return
        if value == LoginMethod.DEVICE:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == LoginMethod.BROWSER:
            buf.write_i32(1)
        if value == LoginMethod.DEVICE:
            buf.write_i32(2)








class ReplayMode:
    """
    Scrollback replay when attaching.
"""
    def __init__(self):
        raise RuntimeError("ReplayMode cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class NONE:
        """
        Live output only.
"""

        def __init__(self, ):
            pass





        def __str__(self):
            return "ReplayMode.NONE()".format()
        def __eq__(self, other):
            if not isinstance(other, ReplayMode):
                return NotImplemented
            if not other.is_NONE():
                return False
            return True

    @dataclass
    class ALL:
        """
        Everything retained.
"""

        def __init__(self, ):
            pass





        def __str__(self):
            return "ReplayMode.ALL()".format()
        def __eq__(self, other):
            if not isinstance(other, ReplayMode):
                return NotImplemented
            if not other.is_ALL():
                return False
            return True

    @dataclass
    class LAST_BYTES:
        """
        The last `n` bytes.
"""

        def __init__(self, n:int):
            self.n = n

            """
        Byte count.
"""

            pass





        def __str__(self):
            return "ReplayMode.LAST_BYTES(n={})".format(self.n)
        def __eq__(self, other):
            if not isinstance(other, ReplayMode):
                return NotImplemented
            if not other.is_LAST_BYTES():
                return False
            if self.n != other.n:
                return False
            return True

    @dataclass
    class FROM_OFFSET:
        """
        From this combined-output offset.
"""

        def __init__(self, offset:int):
            self.offset = offset

            """
        Offset.
"""

            pass





        def __str__(self):
            return "ReplayMode.FROM_OFFSET(offset={})".format(self.offset)
        def __eq__(self, other):
            if not isinstance(other, ReplayMode):
                return NotImplemented
            if not other.is_FROM_OFFSET():
                return False
            if self.offset != other.offset:
                return False
            return True



    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_NONE(self) -> bool:
        return isinstance(self, ReplayMode.NONE)
    def is_none(self) -> bool:
        return isinstance(self, ReplayMode.NONE)
    def is_ALL(self) -> bool:
        return isinstance(self, ReplayMode.ALL)
    def is_all(self) -> bool:
        return isinstance(self, ReplayMode.ALL)
    def is_LAST_BYTES(self) -> bool:
        return isinstance(self, ReplayMode.LAST_BYTES)
    def is_last_bytes(self) -> bool:
        return isinstance(self, ReplayMode.LAST_BYTES)
    def is_FROM_OFFSET(self) -> bool:
        return isinstance(self, ReplayMode.FROM_OFFSET)
    def is_from_offset(self) -> bool:
        return isinstance(self, ReplayMode.FROM_OFFSET)


# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
ReplayMode.NONE = type("ReplayMode.NONE", (ReplayMode.NONE, ReplayMode,), {})  # type: ignore
ReplayMode.ALL = type("ReplayMode.ALL", (ReplayMode.ALL, ReplayMode,), {})  # type: ignore
ReplayMode.LAST_BYTES = type("ReplayMode.LAST_BYTES", (ReplayMode.LAST_BYTES, ReplayMode,), {})  # type: ignore
ReplayMode.FROM_OFFSET = type("ReplayMode.FROM_OFFSET", (ReplayMode.FROM_OFFSET, ReplayMode,), {})  # type: ignore




class _UniffiFfiConverterTypeReplayMode(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return ReplayMode.NONE(
            )
        if variant == 2:
            return ReplayMode.ALL(
            )
        if variant == 3:
            return ReplayMode.LAST_BYTES(
                _UniffiFfiConverterUInt64.read(buf),
            )
        if variant == 4:
            return ReplayMode.FROM_OFFSET(
                _UniffiFfiConverterUInt64.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_NONE():
            return
        if value.is_ALL():
            return
        if value.is_LAST_BYTES():
            _UniffiFfiConverterUInt64.check_lower(value.n)
            return
        if value.is_FROM_OFFSET():
            _UniffiFfiConverterUInt64.check_lower(value.offset)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_NONE():
            buf.write_i32(1)
        if value.is_ALL():
            buf.write_i32(2)
        if value.is_LAST_BYTES():
            buf.write_i32(3)
            _UniffiFfiConverterUInt64.write(value.n, buf)
        if value.is_FROM_OFFSET():
            buf.write_i32(4)
            _UniffiFfiConverterUInt64.write(value.offset, buf)



class _UniffiFfiConverterSequenceTypeAgentArtifact(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        for item in value:
            _UniffiFfiConverterTypeAgentArtifact.check_lower(item)

    @classmethod
    def write(cls, value, buf):
        items = len(value)
        buf.write_i32(items)
        for item in value:
            _UniffiFfiConverterTypeAgentArtifact.write(item, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative sequence length")

        return [
            _UniffiFfiConverterTypeAgentArtifact.read(buf) for i in range(count)
        ]

