class AgentRunProtocol(typing.Protocol):
    """
    One run.
"""

    async def artifacts(self, ) -> typing.List[AgentArtifact]:
        """
        Files the run created or changed in its working directory.
"""
        raise NotImplementedError
    async def events(self, cursor: int,max: typing.Optional[int]) -> AgentEventPage:
        """
        Events after `cursor` (0: from the start), at most `max`.
"""
        raise NotImplementedError
    def harness(self, ) -> str:
        raise NotImplementedError
    async def interrupt(self, ) -> AgentRunInfo:
        """
        Cancels the turn in flight; the session stays open.
"""
        raise NotImplementedError
    async def remove(self, ) -> None:
        """
        Stops the run and deletes its directory (secrets included).
"""
        raise NotImplementedError
    async def result(self, ) -> AgentRunResult:
        """
        The last turn's outcome.
"""
        raise NotImplementedError
    def run_id(self, ) -> str:
        raise NotImplementedError
    async def send(self, text: str,files: typing.Optional[typing.List[AgentFile]]) -> AgentRunInfo:
        """
        A follow-up in the same session (queued while a turn runs).
"""
        raise NotImplementedError
    async def status(self, ) -> AgentRunInfo:
        raise NotImplementedError
    async def stop(self, ) -> AgentRunInfo:
        """
        Stops the run and verifies its process is gone.
"""
        raise NotImplementedError
    async def wait(self, timeout_ms: typing.Optional[int]) -> AgentRunResult:
        """
        Waits until no turn is running (at most `timeout_ms`), then returns
        the result.
"""
        raise NotImplementedError

