class _UniffiFfiConverterTypeMediaSession:
    @staticmethod
    def lift(value: int) -> MediaSession:
        return MediaSession._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: MediaSession):
        if not isinstance(value, MediaSession):
            raise TypeError("Expected MediaSession instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: MediaSession) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> MediaSession:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: MediaSession, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))

